/**
 * Typed accessor for the compiled architectural payload.
 *
 * data/portfolio.payload.json is generated by `npm run pipeline`. Regenerate it
 * whenever a localization node, the schema, or the DAG changes.
 */

import payload from "@/data/portfolio.payload.json";
import type { AgenticPortfolioPayload } from "@/types/portfolio-contract";

const compiled = payload as unknown as AgenticPortfolioPayload;

export const agenticPortfolioPayload: AgenticPortfolioPayload = compiled;

export const notebookCells = compiled.localizationRegistry[
  compiled.metadata.availableLanguages[0]
].notebookCells;

export const architectureDag = compiled.systemArchitectureDAG;
